### Implementation: Naive vs. Segment Tree

```python
import time
import random

class NaiveArray:
    """Implements range sum queries and point updates using a standard array."""
    def __init__(self, data):
        self.data = data[:]

    def update(self, idx, val):
        # Time Complexity: O(1)
        self.data[idx] = val

    def query(self, left, right):
        # Time Complexity: O(N)
        return sum(self.data[left:right + 1])

class SegmentTree:
    """Implements range sum queries and point updates using a Segment Tree."""
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        self._build(data, 1, 0, self.n - 1)

    def _build(self, data, node, start, end):
        # Recurrence: T(n) = 2T(n/2) + O(1) -> O(n)
        if start == end:
            self.tree[node] = data[start]
        else:
            mid = (start + end) // 2
            self._build(data, 2 * node, start, mid)
            self._build(data, 2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, idx, val):
        # Time Complexity: O(log N)
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = val
        else:
            mid = (start + end) // 2
            if start <= idx <= mid:
                self._update(2 * node, start, mid, idx, val)
            else:
                self._update(2 * node + 1, mid + 1, end, idx, val)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, left, right):
        # Time Complexity: O(log N)
        return self._query(1, 0, self.n - 1, left, right)

    def _query(self, node, start, end, left, right):
        if right < start or end < left:
            return 0
        if left <= start and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        return self._query(2 * node, start, mid, left, right) + \
               self._query(2 * node + 1, mid + 1, end, left, right)

def run_benchmark(N=10000, Q=5000):
    """
    Executes benchmark. 
    Note: N and Q are scaled down slightly from 100k/50k for 
    the Naive implementation to finish in reasonable time, as 
    O(N*Q) with 10^5 * 5*10^4 would take hours in Python.
    """
    print(f"Benchmarking with N={N}, Q={Q}...")
    data = [random.randint(1, 100) for _ in range(N)]

    # Pre-generate operations to ensure both structures face the same workload
    ops = []
    for _ in range(Q):
        op_type = random.choice(['update', 'query'])
        if op_type == 'update':
            ops.append(('u', random.randint(0, N-1), random.randint(1, 100)))
        else:
            l = random.randint(0, N-1)
            r = random.randint(l, N-1)
            ops.append(('q', l, r))

    # Naive Benchmark
    naive = NaiveArray(data)
    start_time = time.time()
    for op in ops:
        if op[0] == 'u':
            naive.update(op[1], op[2])
        else:
            naive.query(op[1], op[2])
    naive_time = time.time() - start_time
    print(f"Naive Strategy Time: {naive_time:.4f} seconds")

    # Segment Tree Benchmark
    st = SegmentTree(data)
    start_time = time.time()
    for op in ops:
        if op[0] == 'u':
            st.update(op[1], op[2])
        else:
            st.query(op[1], op[2])
    st_time = time.time() - start_time
    print(f"Segment Tree Time: {st_time:.4f} seconds")
    print(f"Performance Gain: {naive_time / st_time:.2f}x faster")

if __name__ == "__main__":
    # Scaling N and Q to 10k and 5k to demonstrate the gap without crashing Python
    # The O(N) vs O(log N) gap is already massive at this scale.
    run_benchmark(N=10000, Q=5000)
```

